using System.Windows;
using System.Windows.Controls;
using DocumentScanner.Core;
using DocumentScanner.Infrastructure;
namespace DocumentScanner.App;
public sealed class ErpDestinationWindow : Window
{
    private readonly ComboBox sites,types=new(),field=new();private readonly TextBox query=Ui.Input("");private readonly ListBox rows=new(){MinHeight=160,DisplayMemberPath="Name"};private readonly TextBlock detail=Ui.Note("Select a search result to view real document details. Selection does not confirm the destination.");
    private readonly Button confirm;private readonly CheckBox privacy;private readonly TextBlock state=Ui.Note("Not confirmed");private readonly CancellationTokenSource lifetime=new();private ErpClient? client;private ErpDocument? selected;private string account="";private int offset,version;private bool more;
    public ErpTarget? Target{get;private set;}
    public ErpDestinationWindow(IReadOnlyList<ErpSite> available,ErpDefaults defaults,Guid sessionId,string outputSummary)
    {
        Title="Send to ERPNext · Confirm destination";Width=1050;Height=800;MinWidth=800;MinHeight=600;WindowStartupLocation=WindowStartupLocation.CenterOwner;
        var root=new DockPanel{Margin=new(20)};var header=new StackPanel();DockPanel.SetDock(header,Dock.Top);header.Children.Add(new TextBlock{Text="Search → Review → Confirm destination",FontSize=22,FontWeight=FontWeights.SemiBold});header.Children.Add(Ui.Note(outputSummary));header.Children.Add(Ui.BridgeNotice());
        sites=Ui.Choice<ErpSite>(available,null);sites.DisplayMemberPath="Name";Ui.Field(header,"ERPNext Site Profile",sites);Ui.Field(header,"DocType",types);
        var search=new Grid();search.ColumnDefinitions.Add(new());search.ColumnDefinitions.Add(new(){Width=new(190)});search.ColumnDefinitions.Add(new(){Width=GridLength.Auto});search.Children.Add(query);Grid.SetColumn(field,1);search.Children.Add(field);var button=Ui.Button("Search",()=>{});Grid.SetColumn(button,2);search.Children.Add(button);header.Children.Add(search);header.Children.Add(state);root.Children.Add(header);
        var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);privacy=Ui.Check("Private attachment",defaults.Private);bottom.Children.Add(privacy);bottom.Children.Add(Ui.Note("Changing site, account, DocType or document clears confirmation. Confirmation selects a destination; upload starts only after a separate Send action."));var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(Ui.Button("Cancel",()=>DialogResult=false));confirm=Ui.Button("Confirm destination",()=>{},true);confirm.IsEnabled=false;actions.Children.Add(confirm);bottom.Children.Add(actions);root.Children.Add(bottom);
        var grid=new Grid();grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new());var left=new DockPanel();var paging=new WrapPanel();DockPanel.SetDock(paging,Dock.Bottom);paging.Children.Add(Ui.Button("Previous",()=>{offset=Math.Max(0,offset-20);_=Search();}));paging.Children.Add(Ui.Button("Next",()=>{if(more){offset+=20;_=Search();}}));left.Children.Add(paging);left.Children.Add(rows);grid.Children.Add(left);var info=new ScrollViewer{Content=detail,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new(20,0,0,0)};Grid.SetColumn(info,1);grid.Children.Add(info);root.Children.Add(grid);Content=root;
        void Invalidate(){selected=null;Target=null;confirm.IsEnabled=false;state.Text="Not confirmed";version++;}
        sites.SelectionChanged+=async(_,_)=>{Invalidate();rows.ItemsSource=null;types.ItemsSource=null;client?.Dispose();client=null;if(sites.SelectedItem is not ErpSite s)return;await Ui.Guard(async()=>{var credentials=WindowsCredentialStore.Load(s.Id)??throw new InvalidOperationException("No credentials for this Windows user. Open Manage profiles → ERPNext → Manage sites.");var current=new ErpClient(s,credentials);client=current;var v=version;var connection=await current.Connect(lifetime.Token);if(v!=version)return;account=connection.Account;types.ItemsSource=connection.DocTypes;types.SelectedItem=connection.DocTypes.Contains(defaults.DocType)?defaults.DocType:null;state.Text=$"Connected as {account} · Bridge {connection.Version} · Not confirmed";});};
        types.SelectionChanged+=(_,_)=>{Invalidate();rows.ItemsSource=null;field.ItemsSource=new[]{"All"};field.SelectedItem="All";offset=0;};button.Click+=async(_,_)=>{offset=0;await Search();};query.KeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){offset=0;await Search();}};
        rows.SelectionChanged+=async(_,_)=>{Invalidate();if(rows.SelectedItem is not ErpDocument row||client==null)return;int v=version;await Ui.Guard(async()=>{var doc=await client.Document(row.DocType,row.Name,lifetime.Token);if(v!=version)return;selected=doc;detail.Text=$"{doc.DocType} · {doc.Name}\n\nCustomer / supplier: {doc.Party}\n\nDescription: {doc.Description}\n\nCompany: {doc.Company}\nDate: {doc.Date}\nStatus: {doc.Status}\nTotal: {doc.Total}\n\nRevision: {doc.Revision}";confirm.IsEnabled=true;});};
        confirm.Click+=async(_,_)=>await Ui.Guard(async()=>{if(selected==null||client==null)return;confirm.IsEnabled=false;var before=selected;var v=version;var fresh=await client.Document(before.DocType,before.Name,lifetime.Token);if(v!=version)return;if(fresh!=before){selected=fresh;detail.Text=$"Document changed: {fresh.Name}\n{fresh.Party}\n{fresh.Description}\n{fresh.Date} · {fresh.Status} · {fresh.Total}\nReview these details and confirm again.";confirm.IsEnabled=true;return;}Target=new(sessionId,client.Site.Id,account,fresh.DocType,fresh.Name,privacy.IsChecked==true,fresh.Revision,client.Site.Url);DialogResult=true;});
        Closed+=(_,_)=>{lifetime.Cancel();client?.Dispose();lifetime.Dispose();};Loaded+=(_,_)=>{if(defaults.SiteId is {} id)sites.SelectedItem=available.FirstOrDefault(x=>x.Id==id);};
    }
    private Task Search()=>Ui.Guard(async()=>{if(client==null||types.SelectedItem is not string type)throw new ArgumentException("Select a connected site and DocType.");confirm.IsEnabled=false;selected=null;int v=++version;state.Text="Searching… · Not confirmed";var result=await client.Search(type,query.Text,field.SelectedItem as string??"All",offset,lifetime.Token);if(v!=version)return;var chosen=field.SelectedItem as string;field.ItemsSource=result.SearchFields;field.SelectedItem=result.SearchFields.Contains(chosen)?chosen:"All";rows.ItemsSource=result.Rows;more=result.More;state.Text=$"{result.Rows.Count} results · Page {offset/20+1} · Not confirmed";detail.Text="Select a document to verify its real details.";});
}

